/* Enquêtes du volet « Les Grandes Découvertes » (un objet par chapitre, même index que v-decouvertes.js).
   P(titre, document(s), questions primaire, questions collège, indice). Q : la 1re réponse est la bonne.
   Textes anciens : toujours adaptés (jamais cités mot pour mot), source indiquée. */
(function(){
'use strict';
var H=window.EQ;if(!H)return;
var Q=H.Q,V=H.V,O=H.O,T=H.T,R=H.R,W=H.W,I=H.I,X=H.X,M=H.M,TB=H.TB,F=H.F,P=H.P,E=function(ci,o){H.E('decouvertes',ci,o);};

E(0,{q:'Pourquoi les Européens se lancent-ils sur les océans au XVe siècle ?',
h:['Pour le plaisir de voyager','Pour les épices, l’or, la religion et la curiosité','Parce que l’Europe était trop peuplée'],
pg:[
P('Le monde connu vers 1450',I('framauro'),
 [Q('Sur la carte de Fra Mauro, le sud est…',['en haut','en bas','à gauche']),V('Cette carte montre déjà l’Amérique.',0,'Faux : les Européens ne la connaissent pas encore.')],
 [Q('Quelles régions les Européens connaissent-ils vers 1450 ?',['L’Europe, le nord de l’Afrique et une partie de l’Asie','Le monde entier','Seulement l’Europe']),W('Pourquoi chaque peuple connaît-il surtout sa propre région du monde vers 1400 ?','Les voyages sont longs et dangereux ; les connaissances passent de marchand en marchand ; personne n’a encore relié tous les océans.')],
 'Vers 1450, les Européens ignorent l’Amérique et le Pacifique.'),
P('Les épices et la soie',[I('epices'),TB('D’où viennent les produits précieux ?',['Produit','Origine','Usage'],[['poivre','Inde (Calicut)','relever le goût des plats'],['clous de girofle','Moluques','cuisine, médicaments'],['cannelle','Ceylan','cuisine, parfums'],['soie','Chine','tissus de luxe']],'Tableau de l’atlas.')],
 [Q('D’où viennent le poivre et les clous de girofle ?',['D’Asie','D’Amérique','D’Europe']),V('À Venise, les épices valent une fortune.',1)],
 [W('Pourquoi les épices coûtent-elles si cher en Europe ?','Elles viennent de très loin et passent par de nombreux marchands (caravanes, navires), qui prennent chacun un bénéfice.'),Q('Quelle ville d’Italie s’enrichit avec le commerce des épices ?',['Venise','Lisbonne','Paris'])],
 'Épices et soie viennent d’Asie et passent de marchand en marchand : en Europe, elles valent une fortune.'),
P('1453 : Constantinople',I('constantinople'),
 [Q('Qui prend Constantinople en 1453 ?',['Les Ottomans','Les Portugais','Les Vikings']),V('Après 1453, les marchandises d’Asie coûtent encore plus cher.',1)],
 [Q('Pourquoi la prise de Constantinople pousse-t-elle à chercher une autre route ?',['Les Ottomans contrôlent les routes vers l’Asie : il faut passer par eux','Constantinople était la seule ville qui vendait des bateaux','La Méditerranée s’est asséchée']),W('Quelle route le Portugal et l’Espagne veulent-ils trouver ?','Une route par la mer, directement jusqu’en Asie, en contournant l’Afrique ou en traversant l’océan vers l’ouest, sans intermédiaires.')],
 'En 1453, les Ottomans contrôlent les routes vers l’Asie : il faut une autre route, par la mer.'),
P('De nouveaux outils',[I('caravelle'),I('astrolabe')],
 [R('Relie chaque outil à son usage.',[['Caravelle','navire léger et maniable'],['Boussole','indique le nord'],['Astrolabe','mesure la hauteur des astres']]),V('La caravelle est un navire.',1)],
 [W('Pourquoi mesurer la hauteur du Soleil ou d’une étoile aide-t-il les marins ?','Cela permet de calculer la latitude, c’est-à-dire de savoir à quelle distance au nord ou au sud de l’équateur on se trouve.'),Q('Quelles sont les trois grandes raisons de partir ?',['L’or et les épices, répandre la religion chrétienne, la curiosité','Le tourisme, le sport, la pêche','Fuir la guerre, la famine et le froid'])],
 'Caravelle, boussole, astrolabe et meilleures cartes permettent de partir loin ; on part pour l’or, les épices, la religion et la curiosité.')],
f:{p:'Les Européens veulent atteindre l’[Asie] par la mer pour acheter les [épices] sans intermédiaires. Depuis 1453, les [Ottomans] contrôlent les routes. Grâce à la [caravelle] et à l’astrolabe, ils partent.',w:['Amérique','glaces','Vikings'],
 c:['Ils veulent atteindre l’Asie par la mer pour avoir les épices et l’or sans intermédiaires (surtout depuis 1453), répandre le christianisme et connaître le monde, grâce à de nouveaux navires et instruments.','Ils partent en vacances découvrir des plages.','Ils fuient l’Europe, devenue trop petite pour tout le monde.'],
 r:'Les épices et la soie d’Asie passent par de nombreux intermédiaires et coûtent très cher ; depuis la prise de Constantinople (1453), les Ottomans contrôlent les routes. Le Portugal et l’Espagne veulent donc atteindre l’Asie par la mer. Ils partent pour l’or et les épices, pour répandre la religion chrétienne et par curiosité, grâce à la caravelle, la boussole, l’astrolabe et de meilleures cartes.'}});

E(1,{q:'Les Chinois ont-ils exploré les océans avant les Européens ? Pourquoi se sont-ils arrêtés ?',
h:['Non, la Chine n’avait pas de navires','Oui, avec d’immenses flottes, puis la Chine a choisi d’arrêter','Oui, et ils ont découvert l’Europe'],
pg:[
P('Un bateau-trésor',I('zhenghe'),
 [Q('Qui commande la flotte des trésors ?',['L’amiral Zheng He','Christophe Colomb','Magellan']),V('Les plus grandes jonques sont bien plus longues que les caravelles.',1)],
 [Q('Combien d’expéditions Zheng He mène-t-il ?',['Sept, de 1405 à 1433','Une seule','Cent']),W('Pourquoi l’empereur envoie-t-il une flotte aussi immense ?','Pour montrer la puissance de la Chine, échanger des cadeaux, obtenir des ambassadeurs des pays visités et assurer la sécurité des routes de commerce.')],
 'De 1405 à 1433, l’amiral Zheng He mène sept expéditions avec d’immenses jonques.'),
P('Deux flottes face à face',TB('Zheng He et Colomb : deux flottes',['','Zheng He (1405)','Colomb (1492)'],[['Nombre de navires','jusqu’à 300','3'],['Équipage','jusqu’à 27 000 hommes','environ 90 hommes'],['But','montrer la puissance de la Chine','atteindre l’Asie par l’ouest']],'Tableau de l’atlas, chiffres arrondis.'),
 [Q('Combien de navires a Colomb ?',['3','300','30']),V('La flotte de Zheng He est beaucoup plus grande que celle de Colomb.',1)],
 [W('Que montre cette comparaison sur la Chine du début du XVe siècle ?','La Chine est alors la plus grande puissance maritime du monde : sa flotte dépasse de loin celles des Européens.'),Q('Combien d’années séparent le premier voyage de Zheng He et celui de Colomb ?',['87 ans','8 ans','870 ans'])],
 'La flotte de Zheng He (300 navires, 27 000 hommes) est cent fois plus grande que celle de Colomb.'),
P('Une girafe pour l’empereur',I('girafe'),
 [Q('D’où vient la girafe ?',['D’Afrique','D’Europe','D’Amérique']),V('La flotte chinoise va jusqu’en Afrique de l’Est.',1)],
 [Q('Pourquoi rapporter des animaux rares et des ambassadeurs ?',['Pour montrer que des pays lointains reconnaissent la puissance de l’empereur','Pour ouvrir un zoo payant','Pour les vendre aux Européens']),W('Cite trois régions atteintes par la flotte.','L’Asie du Sud-Est (Champa, Malacca), l’Inde et Ceylan (Calicut), l’Arabie (Ormuz, Aden) et l’Afrique de l’Est (Mogadiscio, Malindi).')],
 'La flotte visite l’Asie du Sud-Est, l’Inde, l’Arabie et l’Afrique de l’Est ; elle rapporte une girafe.'),
P('La Chine s’arrête',M(),
 [Q('En quelle année la Chine arrête-t-elle les expéditions ?',['1433','1492','1900']),V('Soixante ans plus tard, les Portugais arrivent dans le même océan.',1)],
 [Q('Pourquoi la Chine arrête-t-elle ?',['Les expéditions sont jugées trop chères','Zheng He a découvert l’Amérique','Toutes les jonques ont coulé']),W('Imagine : si la Chine avait continué, qu’aurait-il pu se passer ?','Réponse libre argumentée : les Chinois auraient pu contourner l’Afrique avant les Portugais, ou garder le contrôle du commerce de l’océan Indien ; l’histoire des « découvertes » aurait été différente.')],
 'En 1433, la Chine arrête ces voyages trop chers ; les Portugais arriveront dans l’océan Indien 60 ans plus tard.')],
f:{p:'De [1405] à 1433, l’amiral [Zheng He] mène sept expéditions sur l’océan [Indien]. Sa flotte est immense. Puis la Chine [arrête], car cela coûte trop cher.',w:['1492','Atlantique','continue'],
 c:['Oui : de 1405 à 1433, Zheng He conduit sept expéditions géantes jusqu’en Arabie et en Afrique, bien avant les Européens ; puis l’empereur arrête ces voyages, jugés trop coûteux.','Non : la Chine n’a jamais construit de grands navires.','Oui : Zheng He a découvert l’Europe et l’Amérique en 1405.'],
 r:'Oui. De 1405 à 1433, l’amiral Zheng He conduit sept expéditions avec jusqu’à 300 navires et 27 000 hommes, de l’Asie du Sud-Est à l’Arabie et à l’Afrique de l’Est (la girafe). Ces voyages montrent la puissance de la Chine. Mais en 1433, la Chine les arrête car ils coûtent trop cher ; soixante ans plus tard, les Portugais arrivent dans l’océan Indien.'}});

E(2,{q:'Comment les Portugais ont-ils trouvé la route du sud de l’Afrique ?',
h:['D’un seul coup, en un seul voyage','Pas à pas, pendant près de 70 ans, en descendant la côte africaine','Par la terre, à cheval'],
pg:[
P('Un monument à Lisbonne',I('padrao'),
 [Q('Où se trouve ce monument ?',['À Lisbonne, au Portugal','À Paris','À Rome']),V('Il rend hommage aux navigateurs portugais.',1)],
 [Q('Ce monument a été construit au XXe siècle. Que montre-t-il ?',['La fierté du Portugal pour ses navigateurs','Un vrai navire du XVe siècle','Le tombeau de Dias']),W('Un monument est-il une source neutre pour l’historien ? Explique.','Non : il montre comment un pays veut se souvenir de son passé. Il célèbre les navigateurs, mais ne montre pas les souffrances (esclavage, conquêtes).')],
 'Le Portugal célèbre aujourd’hui ses navigateurs, menés au début par le prince Henri.'),
P('Pas à pas le long de l’Afrique',F('Les Portugais le long de l’Afrique',[['1420','Madère'],['1427','les Açores'],['1434','le cap Bojador est franchi'],['1444','le Cap-Vert'],['1482','comptoir d’Elmina ; embouchure du fleuve Congo'],['1488','Dias contourne le sud de l’Afrique']]),
 [O('Remets dans l’ordre.',['Madère','cap Bojador','fleuve Congo','sud de l’Afrique']),V('Les Portugais vont un peu plus loin à chaque voyage.',1)],
 [Q('Combien d’années entre Madère (1420) et le voyage de Dias (1488) ?',['68 ans','6 ans','600 ans']),W('Pourquoi le cap Bojador faisait-il peur aux marins ?','Ils le croyaient infranchissable : courants et vents contraires, hauts-fonds, et des légendes sur une mer terrible au-delà.')],
 'Les Portugais avancent pas à pas : Madère (1420), cap Bojador (1434), Cap-Vert, Congo… jusqu’en 1488.'),
P('Le voyage de Dias',X('Bartolomeu Dias, 1487 – 1488','Texte de l’atlas, d’après les chroniques portugaises','En 1487, Bartolomeu Dias quitte Lisbonne avec trois navires. Au sud de l’Afrique, une tempête le pousse au large pendant treize jours. Quand il retrouve la côte, en février 1488, elle file vers l’est : il a contourné l’Afrique sans la voir !\nSon équipage, épuisé, refuse d’aller plus loin. Au retour, Dias longe le grand cap. Selon la tradition, il l’appelle « cap des Tempêtes » ; le roi Jean II préfère « cap de Bonne-Espérance », car la route de l’Inde est ouverte.','En 1487, Dias part de Lisbonne. Au sud de l’Afrique, une tempête le pousse loin de la côte. Quand il revient, il a passé le bout de l’Afrique !\nSes marins sont fatigués : ils rentrent. Le roi appelle le grand cap « Bonne-Espérance » : la route de l’Inde est ouverte.'),
 [Q('Qu’arrive-t-il à Dias au sud de l’Afrique ?',['Une tempête le pousse au large','Il rencontre Colomb','Il trouve une montagne d’or']),T('Le roi appelle le cap « cap de [Bonne-Espérance] ».',['Tempête','Horn'])],
 [W('Pourquoi le roi préfère-t-il « Bonne-Espérance » à « cap des Tempêtes » ?','Ce nom donne de l’espoir : la route de l’Inde par la mer est ouverte. « Tempêtes » aurait fait peur aux marins et à ceux qui paient les voyages.'),V('Dias va jusqu’en Inde.',0,'Faux : son équipage refuse d’aller plus loin ; c’est Vasco de Gama qui atteindra l’Inde, en 1498.')],
 'En 1488, Dias contourne le sud de l’Afrique : c’est le cap de Bonne-Espérance.'),
P('Comptoirs et esclavage',M(),
 [Q('Qu’est-ce qu’un comptoir ?',['Un établissement de commerce sur une côte lointaine','Une table de cuisine','Un navire']),V('Les Portugais rapportent de l’or, mais aussi des hommes et des femmes réduits en esclavage.',1)],
 [Q('Que fait-on au comptoir d’Elmina, fondé en 1482 ?',['On y achète de l’or, puis des esclaves','On y construit des caravelles','On y cultive du blé']),W('Pourquoi l’historien doit-il aussi parler de l’esclavage quand il raconte ces « découvertes » ?','Ces voyages ont aussi commencé la traite des Africains : ne raconter que les exploits des marins donnerait une histoire incomplète.')],
 'Les Portugais créent des comptoirs ; ils achètent de l’or et des esclaves.')],
f:{p:'Les Portugais descendent la côte de l’[Afrique] pas à pas. Ils créent des [comptoirs]. En 1488, [Dias] contourne le sud de l’Afrique : c’est le cap de [Bonne-Espérance].',w:['Amérique','châteaux','Colomb'],
 c:['Pas à pas : à partir de 1420, sous l’impulsion du prince Henri, chaque voyage va un peu plus loin le long de l’Afrique, avec des comptoirs, jusqu’au passage du sud de l’Afrique par Dias en 1488.','En un seul voyage, Dias va directement de Lisbonne à l’Inde.','En traversant le Sahara à cheval.'],
 r:'Les Portugais ont avancé pas à pas pendant près de 70 ans : Madère (1420), les Açores, le cap Bojador (1434), le Cap-Vert, le golfe de Guinée, le Congo (1482), en fondant des comptoirs où ils achètent de l’or et des esclaves. En 1488, Bartolomeu Dias contourne le sud de l’Afrique : le cap de Bonne-Espérance ouvre la route de l’Inde.'}});

E(3,{q:'Christophe Colomb a-t-il vraiment « découvert » l’Amérique ?',
h:['Oui, et il savait qu’il arrivait sur un nouveau continent','Il est arrivé en Amérique, mais se croyait en Asie, et des peuples y vivaient déjà','Non, il n’a jamais traversé l’Atlantique'],
pg:[
P('Le navigateur et son navire',[I('colomb'),I('santamaria')],
 [Q('Comment s’appellent les trois navires de Colomb ?',['Santa María, Pinta et Niña','Victoria, Trinidad et Concepción','Endeavour, Resolution et Adventure']),V('Les rois d’Espagne paient le voyage.',1)],
 [Q('Pourquoi Colomb part-il vers l’ouest ?',['Pour atteindre l’Asie (Japon, Chine) en faisant le tour de la Terre','Pour prouver que la Terre est ronde','Pour trouver un continent inconnu']),W('Colomb savait que la Terre est ronde. Quelle était son erreur ?','Il croyait la Terre bien plus petite : il pensait atteindre l’Asie en quelques semaines. Il ignorait qu’un continent et un immense océan se trouvaient entre l’Europe et l’Asie.')],
 'En 1492, Colomb part vers l’ouest pour atteindre l’Asie ; il croit la Terre bien plus petite qu’elle n’est.'),
P('Le journal de bord',X('12 octobre 1492','Texte adapté, d’après le journal de bord de Christophe Colomb (connu par un résumé de Bartolomé de Las Casas)','Vers deux heures du matin, un marin de la Pinta crie : « Terre ! ». Au jour, Colomb débarque sur une île que ses habitants appellent Guanahani. Il y plante la bannière des rois d’Espagne, en prend possession et la nomme San Salvador.\nIl décrit des gens accueillants, sans armes de fer, qui échangent des perroquets et du coton contre des perles de verre et des clochettes. Il note qu’ils feraient de bons serviteurs et qu’il serait facile d’en faire des chrétiens. Persuadé d’être près des Indes, il les appelle « Indiens ».','La nuit, un marin crie : « Terre ! ». Le matin, Colomb arrive sur une île. Ses habitants l’appellent Guanahani. Colomb dit qu’elle appartient au roi d’Espagne.\nLes habitants sont accueillants. Colomb pense qu’ils pourraient devenir ses serviteurs. Il croit être en Inde : il les appelle « Indiens ».'),
 [Q('Comment Colomb appelle-t-il les habitants ?',['« Indiens »','« Américains »','« Européens »']),V('L’île avait déjà un nom avant l’arrivée de Colomb.',1,'Vrai : ses habitants l’appelaient Guanahani.')],
 [W('Relève ce qui montre que Colomb pense déjà à dominer les habitants.','Il prend possession de l’île sans leur demander et note qu’ils feraient « de bons serviteurs » et qu’on pourrait facilement les convertir.'),Q('Pourquoi ce document est-il précieux, mais à lire avec prudence ?',['C’est le point de vue de Colomb, connu par un résumé : les Taïnos n’ont pas laissé leur version','C’est une photo prise en 1492','C’est un texte écrit par les Taïnos'])],
 'Le 12 octobre 1492, Colomb arrive à Guanahani (Bahamas) ; il se croit aux Indes et appelle les habitants « Indiens ».'),
P('Une image fabriquée plus tard',I('landing'),
 [Q('Cette gravure a été faite…',['au XIXe siècle, plus de 300 ans après','le jour même, en 1492','par les Taïnos']),V('L’artiste a pu imaginer la scène.',1)],
 [W('Peut-on croire cette gravure comme une photo ? Explique.','Non : l’artiste n’était pas là ; il imagine la scène, souvent pour glorifier Colomb. Elle montre surtout comment on voyait cet événement au XIXe siècle.'),Q('Qui est mis en valeur sur cette image ?',['Colomb et les Espagnols','Les Taïnos','Le roi de France'])],
 'Les images de l’arrivée de Colomb ont été faites bien plus tard, pour le célébrer.'),
P('Quatre voyages',[F('Les voyages de Colomb',[['1492 – 1493','1er voyage : Bahamas, Cuba, Hispaniola'],['1493','2e voyage : Guadeloupe et Petites Antilles'],['1498','3e voyage : Trinité, côte du Venezuela'],['1502 – 1504','4e voyage : Amérique centrale (Panama)'],['1506','mort de Colomb, toujours persuadé d’avoir atteint l’Asie']]),I('lacosa')],
 [Q('Combien de voyages Colomb fait-il en Amérique ?',['Quatre','Un','Dix']),V('Colomb meurt en sachant qu’il a atteint un nouveau continent.',0,'Faux : il meurt en 1506, persuadé d’être allé en Asie.')],
 [Q('Qu’arrive-t-il aux Taïnos dans les années qui suivent ?',['Travail forcé, violences et maladies les font presque tous disparaître','Ils deviennent rois d’Espagne','Ils partent vivre en Europe']),W('Pourquoi les historiens préfèrent-ils parler d’« arrivée » ou de « rencontre » plutôt que de « découverte » ?','Parce que l’Amérique était habitée depuis des milliers d’années : elle n’était « nouvelle » que pour les Européens.')],
 'Colomb fait quatre voyages et meurt en se croyant en Asie ; pour les Taïnos, son arrivée est une catastrophe.')],
f:{p:'En 1492, [Colomb] traverse l’Atlantique. Il arrive aux [Bahamas], mais il se croit en [Asie]. Les habitants, les [Taïnos], vivaient là depuis longtemps.',w:['Magellan','Australie','Vikings'],
 c:['Colomb atteint l’Amérique en 1492, mais il se croit en Asie jusqu’à sa mort ; ces terres étaient habitées depuis des milliers d’années, elles n’étaient « nouvelles » que pour les Européens.','Colomb savait qu’il découvrait un continent vide.','Colomb est arrivé en Inde, comme il l’avait prévu.'],
 r:'Colomb traverse l’Atlantique et atteint les Bahamas le 12 octobre 1492, puis Cuba et Hispaniola. Mais il se croit en Asie (il appelle les habitants « Indiens ») et meurt en 1506 sans savoir qu’il a atteint un continent inconnu des Européens. Surtout, ces terres étaient habitées : pour les Taïnos, son arrivée signifie travail forcé, violences et maladies. On parle donc plutôt d’arrivée ou de rencontre.'}});

E(4,{q:'Comment Vasco de Gama a-t-il ouvert la route des épices par la mer ?',
h:['En traversant l’Afrique à pied','En contournant l’Afrique, aidé par un pilote de l’océan Indien','En passant par l’Amérique'],
pg:[
P('Le capitaine',I('gama'),
 [Q('De quel pays part Vasco de Gama ?',['Du Portugal','D’Espagne','De Chine']),V('Il part en 1497 avec quatre navires.',1)],
 [Q('Quel est le but de son voyage ?',['Atteindre l’Inde par la mer en contournant l’Afrique','Trouver l’Amérique','Faire le tour du monde']),W('Pourquoi le voyage de Dias (1488) a-t-il préparé celui de Gama ?','Dias avait prouvé qu’on pouvait passer le sud de l’Afrique : la route vers l’océan Indien était ouverte.')],
 'En 1497, Vasco de Gama quitte Lisbonne avec quatre navires pour atteindre l’Inde.'),
P('Le grand détour',X('La volta do mar','Texte de l’atlas','Pour descendre l’Atlantique, on ne peut pas longer la côte africaine : les vents et les courants sont contraires. Vasco de Gama fait donc un immense détour par le large, en arc de cercle : c’est la « volta do mar », le tour par la mer.\nPendant environ trois mois, ses marins ne voient aucune terre. C’est bien plus long que la traversée de Colomb ! Puis les vents d’ouest le ramènent vers le sud de l’Afrique.','Le long de l’Afrique, le vent souffle dans le mauvais sens. Alors Vasco de Gama passe très loin de la côte.\nPendant trois mois, ses marins ne voient pas la terre. Puis le vent les pousse vers le sud de l’Afrique.'),
 [Q('Combien de temps les marins restent-ils sans voir la terre ?',['Environ trois mois','Une journée','Dix ans']),V('Gama longe la côte africaine tout le long.',0,'Faux : il fait un grand détour par le large pour trouver de bons vents.')],
 [W('Pourquoi faire un détour aussi long plutôt que suivre la côte ?','Le long de la côte, vents et courants sont contraires ; au large, on trouve des vents qui ramènent vers le sud de l’Afrique : plus long en distance, mais plus sûr et plus rapide.'),Q('Que veut dire « volta do mar » ?',['Le tour par la mer','Le voleur de la mer','La mer calme'])],
 'Gama fait un grand détour par le large (volta do mar) : trois mois sans voir la terre.'),
P('Le voyage, étape par étape',F('Le voyage de Vasco de Gama',[['8 juillet 1497','départ de Lisbonne'],['novembre 1497','passage du cap de Bonne-Espérance'],['avril 1498','à Malindi, un pilote de l’océan Indien rejoint la flotte'],['20 mai 1498','arrivée à Calicut, en Inde'],['1499','retour : deux navires et une cinquantaine d’hommes sur environ 170']]),
 [O('Remets dans l’ordre.',['Lisbonne','cap de Bonne-Espérance','Malindi','Calicut']),V('Un pilote de l’océan Indien aide les Portugais.',1)],
 [Q('Que connaît le pilote de Malindi ?',['La mousson, ces vents qui changent de sens selon la saison','Le chemin de l’Amérique','La langue portugaise']),W('Sur environ 170 hommes, une cinquantaine rentrent. Que montre ce chiffre ?','Ces voyages sont terriblement dangereux : scorbut, tempêtes, combats. Plus de deux marins sur trois sont morts.')],
 'À Malindi, un pilote qui connaît la mousson guide la flotte : en 23 jours, elle traverse l’océan Indien.'),
P('Calicut, au pays du poivre',[I('calicut'),M()],
 [Q('Que trouvent les Portugais à Calicut ?',['Le poivre et les épices','De l’or d’Amérique','Des pommes de terre']),V('Ce tableau a été peint en 1898, 400 ans après.',1)],
 [Q('Pourquoi l’arrivée à Calicut change-t-elle le commerce des épices ?',['Le Portugal peut acheter les épices en Inde, sans passer par Venise ni par les Ottomans','Les épices deviennent gratuites','L’Inde arrête de vendre des épices']),W('Les cadeaux apportés par les Portugais sont jugés bien pauvres à Calicut. Qu’est-ce que cela nous apprend ?','L’océan Indien est déjà un monde riche, plein de grands marchands : les Portugais y arrivent comme des nouveaux venus, pas comme des maîtres.')],
 'Le 20 mai 1498, Gama arrive à Calicut : la route maritime des épices est ouverte.')],
f:{p:'En 1497, [Vasco de Gama] quitte Lisbonne. Il contourne l’[Afrique] par un grand détour. Un pilote le guide grâce à la [mousson]. En 1498, il arrive à [Calicut], en Inde.',w:['Colomb','Amérique','boussole'],
 c:['Il contourne l’Afrique par un immense détour au large, remonte la côte est de l’Afrique, puis un pilote de l’océan Indien le guide grâce à la mousson jusqu’à Calicut, en 1498.','Il traverse l’Afrique à pied avec des chameaux.','Il traverse l’Atlantique vers l’ouest et arrive en Inde par l’Amérique.'],
 r:'Parti de Lisbonne en juillet 1497, Vasco de Gama fait un grand détour par le large (volta do mar), passe le cap de Bonne-Espérance, remonte la côte est de l’Afrique jusqu’à Malindi. Là, un pilote qui connaît la mousson le guide à travers l’océan Indien jusqu’à Calicut (20 mai 1498). Le Portugal peut désormais acheter les épices sans intermédiaires, mais le voyage a coûté la vie à plus de deux marins sur trois.'}});

E(5,{q:'Pourquoi parle-t-on portugais au Brésil ?',
h:['Parce que les habitants du Brésil ont choisi cette langue','Parce qu’un traité et le voyage de Cabral ont donné le Brésil au Portugal','Parce que le Brésil est tout près du Portugal'],
pg:[
P('Le traité de Tordesillas',I('tordesillas'),
 [Q('Qui se partage le monde en 1494 ?',['L’Espagne et le Portugal','La France et l’Angleterre','La Chine et le Japon']),V('Une ligne imaginaire traverse l’océan Atlantique.',1)],
 [Q('Qui donne son accord à ce partage ?',['Le pape','Les habitants de l’Amérique','Le roi de France']),W('Pourquoi ce traité est-il injuste pour les peuples concernés ?','Personne n’a demandé leur avis aux habitants de ces terres, qui y vivaient depuis des milliers d’années.')],
 'En 1494, l’Espagne et le Portugal se partagent le monde à découvrir par le traité de Tordesillas.'),
P('La ligne sur une carte',I('cantino'),
 [Q('Que voit-on sur ce planisphère ?',['La ligne de Tordesillas','Les routes des avions','Les frontières d’aujourd’hui']),T('L’ouest de la ligne revient à l’[Espagne], l’est au Portugal.',['France','Angleterre'])],
 [Q('De quel côté de la ligne se trouve l’est du Brésil ?',['À l’est : côté portugais','À l’ouest : côté espagnol','Exactement sur la ligne']),W('Pourquoi la France et l’Angleterre refusent-elles ce partage ?','Elles veulent elles aussi explorer et commercer, et ne reconnaissent pas un partage décidé sans elles ; François Ier enverra Jacques Cartier.')],
 'La ligne de Tordesillas : l’ouest pour l’Espagne, l’est pour le Portugal.'),
P('La lettre au roi',X('Lettre de Pero Vaz de Caminha au roi Manuel, 1er mai 1500','Texte adapté, d’après la lettre de Pero Vaz de Caminha, écrivain de la flotte de Cabral','Le 22 avril, nous avons vu une terre : d’abord une grande montagne ronde, puis une côte basse couverte de grands arbres. Le capitaine l’a nommée Terre de la Vraie-Croix.\nLes habitants sont venus sur la plage, sans vêtements, avec des arcs et des flèches. Ils ont posé leurs arcs quand on leur a fait signe. Ils n’ont ni bœufs ni poules, et la poule qu’on leur a montrée leur a fait peur.\nCette terre est si grande et si belle que tout y pousserait. Mais le meilleur profit à en tirer serait, je crois, de convertir ces gens.','Le 22 avril, nous voyons une terre avec une grande montagne et des forêts. Des habitants arrivent sur la plage. Ils posent leurs arcs.\nIls n’ont jamais vu de poule ! Cette terre est grande et belle. Le roi pourrait y planter beaucoup de choses et faire de ces gens des chrétiens.'),
 [Q('Quel nom les Portugais donnent-ils d’abord à cette terre ?',['Terre de la Vraie-Croix','Amérique','Nouvelle-Calédonie']),V('Les habitants n’ont jamais vu de poule.',1)],
 [W('Quels sont les deux intérêts du Portugal pour cette terre, d’après la lettre ?','Exploiter une terre très fertile, et convertir ses habitants au christianisme.'),Q('Qui a écrit ce document, et pour qui ?',['Un membre de l’expédition, pour le roi du Portugal','Un habitant du Brésil, pour son chef','Un journaliste, pour un journal'])],
 'Le 22 avril 1500, la flotte de Cabral aborde le Brésil ; une lettre au roi décrit la terre et ses habitants.'),
P('Cabral au Brésil',[I('cabral'),M()],
 [Q('En quelle année Cabral arrive-t-il au Brésil ?',['1500','1492','1600']),V('Cabral voulait aller en Inde.',1)],
 [Q('Pourquoi Cabral passe-t-il si près du Brésil alors qu’il va en Inde ?',['Pour trouver les bons vents, sa flotte s’écarte très loin vers l’ouest','Il s’est perdu dans le brouillard','Il voulait trouver l’Amérique']),W('Ce tableau a été peint plus de 400 ans après. Peut-il montrer exactement ce qui s’est passé ?','Non : le peintre imagine la scène. Il montre comment on voulait se souvenir de l’événement à son époque, souvent pour le célébrer.')],
 'Le Brésil est à l’est de la ligne : Cabral en prend possession pour le Portugal.')],
f:{p:'En [1494], l’Espagne et le Portugal se partagent le monde par le traité de [Tordesillas]. En 1500, [Cabral] arrive au Brésil, à l’est de la ligne : le Brésil devient [portugais].',w:['1789','Versailles','espagnol'],
 c:['Le traité de Tordesillas (1494) donne au Portugal les terres à l’est de la ligne ; en 1500, Cabral aborde le Brésil, situé de ce côté, et en prend possession : le Portugal le colonise.','Parce que les habitants du Brésil parlaient déjà portugais avant 1500.','Parce que Christophe Colomb était portugais.'],
 r:'En 1494, le traité de Tordesillas partage le monde à découvrir entre l’Espagne (à l’ouest d’une ligne) et le Portugal (à l’est). En 1500, la flotte de Cabral, partie pour l’Inde, s’écarte vers l’ouest pour trouver les vents et aborde le Brésil, qui se trouve à l’est de la ligne. Cabral en prend possession pour le Portugal, qui le colonise : voilà pourquoi on y parle portugais. Les habitants, eux, n’ont jamais été consultés.'}});

E(6,{q:'Pourquoi le continent s’appelle-t-il « Amérique » et pas « Colombie » ?',
h:['Parce qu’Amerigo Vespucci y est arrivé le premier','Parce qu’un cartographe l’a nommé d’après Amerigo Vespucci, qui avait compris que c’était un « Nouveau Monde »','Parce que c’est le nom que lui donnaient ses habitants'],
pg:[
P('Un Florentin au service du Portugal',I('vespucci'),
 [Q('D’où vient Amerigo Vespucci ?',['De Florence, en Italie','De Lisbonne','De Paris']),V('Il embarque sur une flotte portugaise en 1501.',1)],
 [Q('Quelle terre son expédition explore-t-elle ?',['La côte trouvée par Cabral (le Brésil)','L’Inde','Terre-Neuve']),W('Pourquoi un Florentin navigue-t-il pour le Portugal ?','Les marins, savants et marchands italiens sont très recherchés : ils se mettent au service des rois qui paient les expéditions.')],
 'En 1501, Amerigo Vespucci, un Florentin, explore pour le Portugal la côte trouvée par Cabral.'),
P('Des noms tirés du calendrier',TB('Des lieux nommés d’après le jour de leur découverte',['Date','Nom donné','Pourquoi ?'],[['16 août 1501','cap São Roque','fête de saint Roch'],['1er novembre 1501','baie de Tous-les-Saints','fête de la Toussaint'],['1er janvier 1502','Rio de Janeiro','« rivière de janvier »']],'Tableau de l’atlas.'),
 [Q('Que veut dire « Rio de Janeiro » ?',['Rivière de janvier','Ville du roi','Mer chaude']),V('Certains lieux sont nommés d’après le jour de leur découverte.',1)],
 [W('Pourquoi « rivière » de janvier, alors qu’il n’y a pas de grand fleuve à cet endroit ?','Les marins ont pris l’entrée de la grande baie pour l’embouchure d’un fleuve ; ils l’ont nommée d’après la date, le 1er janvier.'),Q('Que montrent ces noms sur les explorateurs ?',['Ils sont chrétiens et suivent le calendrier des fêtes religieuses','Ils parlent la langue des habitants','Ils ne savent pas lire un calendrier'])],
 'Les explorateurs nomment les lieux d’après le calendrier : Tous-les-Saints, Rio de Janeiro…'),
P('« Un Nouveau Monde »',X('Mundus Novus','Texte adapté, d’après la lettre « Mundus Novus » attribuée à Amerigo Vespucci (vers 1503)','J’ai trouvé, dans ces régions du sud, un continent plus peuplé d’hommes et d’animaux que notre Europe, l’Asie ou l’Afrique. On peut l’appeler un Nouveau Monde, puisque nos ancêtres n’en avaient aucune connaissance et que c’est une chose toute nouvelle pour ceux qui l’apprennent.','Vespucci écrit : « J’ai trouvé au sud un très grand continent. Les anciens savants ne le connaissaient pas. C’est un Nouveau Monde. »'),
 [Q('Pour Vespucci, cette terre est…',['un continent inconnu des Européens','l’Asie','une petite île']),V('Colomb pensait comme Vespucci.',0,'Faux : Colomb s’est cru en Asie jusqu’à sa mort.')],
 [W('Pourquoi l’idée de « Nouveau Monde » bouleverse-t-elle les Européens ?','Elle montre qu’il existe un continent dont les savants anciens ne parlaient pas : il faut refaire les cartes et revoir les connaissances.'),Q('« Nouveau » pour qui ?',['Pour les Européens seulement','Pour tous les peuples du monde','Pour les habitants de ce continent'])],
 'Pour Vespucci, cette terre n’est pas l’Asie : c’est un continent inconnu des Européens, un « Nouveau Monde ».'),
P('Saint-Dié, 1507',[I('waldsee'),M()],
 [Q('Où cette carte de 1507 a-t-elle été faite ?',['À Saint-Dié, dans les Vosges','À Lisbonne','À New York']),T('Le cartographe écrit le mot [America] sur sa carte.',['Colombia','Vespucia'])],
 [Q('Pourquoi Waldseemüller choisit-il ce nom ?',['En l’honneur d’Amerigo Vespucci, qui avait décrit ce « Nouveau Monde »','Parce que c’était le nom donné par les habitants','En l’honneur d’un roi']),W('Pourquoi dit-on parfois que Colomb a été « oublié » dans le nom du continent ?','Il y est arrivé le premier parmi les Européens de son temps, mais c’est Vespucci qui a compris qu’il s’agissait d’un nouveau continent ; le nom choisi par le cartographe est resté.')],
 'En 1507, à Saint-Dié, Waldseemüller écrit « America » sur sa carte, en l’honneur d’Amerigo.')],
f:{p:'[Vespucci] longe la côte du Brésil. Il comprend que c’est un [continent] inconnu des Européens : un « Nouveau [Monde] ». En 1507, un cartographe écrit [America] sur sa carte.',w:['Colomb','océan','Asia'],
 c:['Parce que Vespucci a compris et fait connaître que ces terres formaient un continent inconnu des Européens, et qu’en 1507 le cartographe Waldseemüller l’a nommé « America » en son honneur.','Parce que Vespucci est arrivé en Amérique avant Colomb.','Parce que les Amérindiens appelaient leur continent « America ».'],
 r:'Colomb s’est cru en Asie. Amerigo Vespucci, qui explore la côte du Brésil en 1501 – 1502, affirme que ces terres forment un continent inconnu des Européens, un « Nouveau Monde ». En 1507, à Saint-Dié, le cartographe Martin Waldseemüller écrit « America » sur sa carte du monde, en l’honneur d’Amerigo. Le nom est resté.'}});

E(7,{q:'Comment le premier tour du monde a-t-il été réalisé, et à quel prix ?',
h:['Facilement, en quelques mois','En trois ans, au prix de la vie de presque tout l’équipage','Sans jamais quitter l’Europe'],
pg:[
P('Le capitaine',I('magellan'),
 [Q('Pour quel roi Magellan navigue-t-il ?',['Le roi d’Espagne','Le roi du Portugal','Le roi de France']),V('Magellan part en 1519 avec cinq navires.',1)],
 [Q('Quel est le but de Magellan ?',['Atteindre les Moluques, les îles aux épices, par l’ouest','Faire le tour du monde pour le plaisir','Trouver l’Australie']),W('Pourquoi Magellan, qui est portugais, navigue-t-il pour l’Espagne ?','Le roi du Portugal a refusé son projet ; Charles Quint l’accepte, car l’Espagne espère montrer que les Moluques sont de son côté de la ligne de Tordesillas.')],
 'En 1519, Magellan part pour l’Espagne avec 5 navires et environ 240 hommes, vers les îles aux épices.'),
P('Le passage',I('detroit'),
 [Q('Combien de jours faut-il pour traverser le détroit ?',['38 jours','3 jours','380 jours']),V('Un détroit est un passage entre deux mers.',1)],
 [W('Pourquoi Magellan appelle-t-il le nouvel océan « Pacifique » ?','Après les tempêtes et les dangers du détroit, il le trouve calme : « pacifique » veut dire paisible.'),Q('Où se trouve ce détroit ?',['Tout au sud de l’Amérique','Entre l’Afrique et l’Europe','Au nord du Canada'])],
 'En 1520, Magellan trouve un passage tout au sud de l’Amérique et entre dans un océan qu’il nomme « Pacifique ».'),
P('Le récit d’un survivant',X('La traversée du Pacifique','Texte adapté, d’après le récit d’Antonio Pigafetta, qui fit tout le voyage','Nous sommes restés trois mois et vingt jours sans manger de nourriture fraîche. Le biscuit n’était plus qu’une poussière pleine de vers, qui sentait l’urine des rats. Nous buvions une eau jaunie, croupie depuis des jours. Nous avons mangé les peaux de cuir qui protégeaient les vergues, après les avoir fait tremper dans la mer, et même de la sciure de bois. Un rat se vendait très cher.\nLes gencives de beaucoup d’hommes gonflaient tellement qu’ils ne pouvaient plus manger : ils en mouraient.','Pendant plus de trois mois, les marins n’ont rien de frais à manger. Le biscuit est plein de vers. L’eau est sale. Ils mangent du cuir et de la sciure de bois.\nBeaucoup tombent malades : leurs gencives gonflent. Beaucoup meurent.'),
 [Q('Que mangent les marins à la fin ?',['Du cuir et de la sciure de bois','Des fruits frais','Du chocolat']),V('Beaucoup de marins tombent malades.',1)],
 [Q('De quelle maladie parle Pigafetta, sans la nommer ?',['Le scorbut, dû au manque de fruits et légumes frais','La grippe','Le paludisme']),W('Pourquoi le récit de Pigafetta est-il une source très précieuse ?','C’est un témoin direct : il a fait tout le voyage, pris des notes et fait partie des 18 survivants.')],
 'Pendant la traversée du Pacifique (plus de trois mois), faim et scorbut tuent beaucoup de marins.'),
P('Le bilan',[I('victoria'),TB('L’expédition au départ et au retour',['','Au départ (1519)','Au retour (1522)'],[['Navires','5','1 (la Victoria)'],['Hommes','environ 240','18'],['Chef','Magellan','Elcano']],'Tableau de l’atlas.')],
 [Q('Combien d’hommes rentrent en 1522 ?',['18','240','2 400']),V('Magellan rentre en Espagne en héros.',0,'Faux : il est tué aux Philippines en 1521 ; c’est Elcano qui ramène la Victoria.')],
 [W('Qu’a prouvé ce voyage ?','Par l’expérience, que la Terre est ronde, que tous les océans communiquent, et que le Pacifique est immense.'),Q('Qui ramène la Victoria en Espagne ?',['Juan Sebastián Elcano','Magellan','Lapu-Lapu'])],
 'Magellan est tué à Mactan ; Elcano ramène la Victoria en 1522 avec 18 hommes sur 240 : premier tour du monde.')],
f:{p:'En 1519, [Magellan] part d’Espagne avec cinq navires. Il franchit un [détroit] au sud de l’Amérique et traverse le [Pacifique]. Il est tué aux Philippines. En 1522, [18] hommes rentrent avec Elcano.',w:['Colomb','pont','180'],
 c:['En trois ans (1519 – 1522), par le détroit de Magellan, le Pacifique et le cap de Bonne-Espérance ; Magellan est tué et seuls 18 hommes sur environ 240 rentrent avec Elcano.','En trois mois, sans aucune perte.','Magellan fait seul le tour du monde et rentre en héros.'],
 r:'Parti de Sanlúcar en 1519 avec 5 navires et environ 240 hommes, Magellan longe l’Amérique du Sud, franchit le détroit qui porte son nom (38 jours) et traverse le Pacifique (plus de trois mois de faim et de scorbut). Il est tué à Mactan en 1521. Elcano ramène la Victoria par l’océan Indien et le cap de Bonne-Espérance : le 6 septembre 1522, 18 survivants bouclent le premier tour du monde.'}});

E(8,{q:'Jacques Cartier a-t-il trouvé ce qu’il cherchait au Canada ?',
h:['Oui : de l’or et un passage vers l’Asie','Non : ni or ni passage, mais il a exploré le Saint-Laurent grâce aux Iroquoiens','Il n’est jamais arrivé en Amérique'],
pg:[
P('Le Malouin',I('cartier'),
 [Q('Quel roi envoie Jacques Cartier ?',['François Ier, roi de France','Charles Quint','Louis XVI']),V('Cartier part de Saint-Malo en 1534.',1)],
 [Q('Que cherche Cartier ?',['Un passage vers l’Asie par le nord, et de l’or','Des épices en Afrique','Le pôle Sud']),W('Pourquoi François Ier refuse-t-il le partage du monde de Tordesillas ?','Il ne veut pas laisser les terres et les richesses du monde à l’Espagne et au Portugal : la France veut aussi sa part.')],
 'En 1534, François Ier envoie Cartier chercher un passage vers l’Asie et de l’or.'),
P('Une croix à Gaspé',X('Gaspé, 24 juillet 1534','Texte adapté, d’après le récit du premier voyage de Jacques Cartier','Nous avons fait faire une croix de trente pieds de haut, avec un écusson à fleurs de lys et l’inscription « Vive le roi de France ». Nous l’avons plantée devant les gens du pays.\nLeur chef est venu dans une barque avec ses fils, vêtu d’une vieille peau d’ours noir. Il nous a fait un long discours en montrant la croix, puis la terre tout autour, comme pour dire que toute cette terre était à lui et qu’il ne fallait pas planter de croix sans sa permission.','Cartier plante une très grande croix avec le nom du roi de France.\nLe chef des Iroquoiens arrive. Il montre la croix, puis la terre. Il veut dire : « Cette terre est à nous. Vous n’avez pas le droit. »'),
 [Q('Qu’est-ce que Cartier plante à Gaspé ?',['Une grande croix','Un arbre','Un drapeau anglais']),V('Le chef iroquoien est content qu’on plante cette croix.',0,'Faux : il proteste, en montrant que la terre est à lui.')],
 [W('Que signifie la croix pour Cartier, et pour le chef Donnacona ?','Pour Cartier, elle montre que le roi de France prend possession de la terre ; pour Donnacona, c’est une installation sans permission sur la terre de son peuple.'),Q('Qui raconte la scène ?',['Les Français, dans le récit du voyage','Donnacona lui-même','Un historien d’aujourd’hui'])],
 'À Gaspé, Cartier plante une croix au nom du roi ; le chef Donnacona proteste.'),
P('Deux voyages',TB('Les deux premiers voyages de Cartier',['Voyage','Navires','Ce qu’il explore'],[['1534','2 navires, 61 hommes','Terre-Neuve, golfe du Saint-Laurent, Gaspé'],['1535 – 1536','3 navires','fleuve Saint-Laurent, Stadaconé (Québec), Hochelaga (Montréal)']],'Tableau de l’atlas.'),
 [Q('Quel grand fleuve Cartier remonte-t-il en 1535 ?',['Le Saint-Laurent','Le Mississippi','L’Amazone']),R('Relie le nom iroquoien à la ville d’aujourd’hui.',[['Stadaconé','Québec'],['Hochelaga','Montréal']])],
 [Q('Qui guide Cartier sur le fleuve ?',['Les deux fils de Donnacona, emmenés en France l’année précédente','Un pilote portugais','Personne']),W('Pourquoi les deux jeunes Iroquoiens sont-ils précieux pour Cartier ?','Ils connaissent le pays et ont appris un peu de français en France : ils servent de guides et d’interprètes.')],
 'En 1535, guidé par deux jeunes Iroquoiens, Cartier remonte le Saint-Laurent jusqu’à Québec et Montréal.'),
P('Un hiver terrible',M(),
 [Q('Qui sauve les marins malades du scorbut ?',['Les Iroquoiens, avec une tisane de conifère','Un médecin anglais','Personne']),T('Le mot « Canada » vient de « [kanata] », qui veut dire le village.',['Kanak','canard'])],
 [W('Que montre l’épisode de la tisane sur les savoirs des Iroquoiens ?','Ils connaissent très bien leur environnement et ses remèdes : sans eux, bien plus de Français seraient morts.'),V('Cartier a trouvé de l’or et un passage vers l’Asie.',0,'Faux : il ne trouve ni l’un ni l’autre, mais il ouvre la voie à la Nouvelle-France.')],
 'Pris dans les glaces, les Français sont sauvés du scorbut par une tisane des Iroquoiens ; « Canada » vient de « kanata ».')],
f:{p:'En 1534, [Cartier] part de Saint-Malo. Il cherche un passage vers l’[Asie]. Il remonte le fleuve [Saint-Laurent]. Les Iroquoiens le sauvent du [scorbut].',w:['Colomb','Afrique','rhume'],
 c:['Non : il ne trouve ni or ni passage vers l’Asie, mais il explore le golfe et le fleuve Saint-Laurent, guidé puis soigné par les Iroquoiens, et ouvre la voie à la Nouvelle-France.','Oui : il rapporte des tonnes d’or et trouve la route de la Chine.','Il n’a jamais quitté la France.'],
 r:'Cartier cherchait de l’or et un passage vers l’Asie par le nord : il n’a trouvé ni l’un ni l’autre. Mais en 1534 et 1535 – 1536, il explore Terre-Neuve, le golfe puis le fleuve Saint-Laurent jusqu’à Stadaconé (Québec) et Hochelaga (Montréal), guidé par les fils de Donnacona. Les Iroquoiens le sauvent du scorbut ; le nom « Canada » vient de leur langue. Son voyage ouvre la voie à la Nouvelle-France.'}});

E(9,{q:'Les Espagnols ont-ils trouvé le grand continent du Sud qu’ils cherchaient ?',
h:['Oui, ils ont trouvé l’Australie','Non : ils ont trouvé des archipels de Mélanésie, mais ni l’or ni le continent rêvé','Oui, ils ont découvert la Nouvelle-Calédonie'],
pg:[
P('L’or du roi Salomon',X('À la recherche d’îles pleines d’or','Texte de l’atlas','En 1567, au Pérou, les Espagnols ont trouvé de l’or et de l’argent. Ils rêvent de nouvelles richesses à l’ouest : une légende parle d’îles d’où le roi Salomon aurait tiré son or. Álvaro de Mendaña part de Callao avec deux navires.\nAprès 80 jours de mer, il atteint une grande île, Santa Isabel. Il n’y trouve pas d’or, et les affrontements avec les habitants se multiplient. Il repart, mais l’archipel gardera le nom d’« îles Salomon ».','Au Pérou, les Espagnols rêvent d’îles pleines d’or. En 1567, Mendaña part les chercher.\nIl arrive sur une grande île. Il ne trouve pas d’or. Mais on appelle ces îles « les îles Salomon ».'),
 [Q('Que cherchent les Espagnols ?',['Des îles pleines d’or','Des épices','Une route vers la France']),V('Mendaña trouve beaucoup d’or.',0,'Faux : il n’en trouve pas.')],
 [W('Pourquoi l’archipel s’appelle-t-il encore « îles Salomon » ?','Les Espagnols espéraient y trouver l’or légendaire du roi Salomon ; ils n’en ont pas trouvé, mais le nom est resté.'),Q('D’où part l’expédition ?',['De Callao, au Pérou','De Séville','De Manille'])],
 'En 1568, Mendaña atteint les îles Salomon, mais il n’y trouve pas d’or.'),
P('Trois expéditions',[I('quiros'),TB('Les expéditions espagnoles vers le Pacifique sud',['Année','Chef','Où ?'],[['1567 – 1569','Álvaro de Mendaña','îles Salomon'],['1595','Mendaña, puis sa femme Isabel Barreto','Marquises, Santa Cruz, puis Manille'],['1606','Pedro Fernández de Quirós','Espiritu Santo (Vanuatu)'],['1606','Luis Váez de Torres','détroit entre la Nouvelle-Guinée et l’Australie']],'Tableau de l’atlas.')],
 [Q('Qui prend le commandement à la mort de Mendaña ?',['Sa femme, Isabel Barreto','Le roi d’Espagne','Magellan']),O('Range dans l’ordre.',['Mendaña aux Salomon','Isabel Barreto conduit la flotte à Manille','Quirós au Vanuatu'])],
 [W('Pourquoi le rôle d’Isabel Barreto est-il exceptionnel pour l’époque ?','Les femmes ne commandaient presque jamais de navires ; elle conduit pourtant la flotte jusqu’à Manille après la mort de son mari.'),Q('Quel nom Quirós donne-t-il à la grande île du Vanuatu ?',['Austrialia del Espíritu Santo','Nouvelle-Calédonie','Terre de Van Diemen'])],
 'En 1595, Isabel Barreto mène la flotte jusqu’à Manille ; en 1606, Quirós croit avoir trouvé le continent au Vanuatu.'),
P('Un continent imaginaire',X('Terra Australis','Texte de l’atlas','Depuis l’Antiquité, des savants pensaient qu’un immense continent devait exister au sud, pour « équilibrer » les terres du nord. On l’appelait Terra Australis, la Terre australe. Les cartes du XVIe siècle le dessinent souvent, immense, en bas du monde.\nQuirós croit l’avoir trouvé au Vanuatu. Il faudra attendre James Cook, en 1774, pour prouver que ce grand continent tempéré et riche n’existe pas.','Des savants imaginaient un très grand continent au sud du monde : la « Terre australe ». Ils le dessinaient sur leurs cartes, sans l’avoir vu.\nQuirós croit l’avoir trouvé. Mais en 1774, James Cook montre qu’il n’existe pas.'),
 [Q('Que veut dire Terra Australis ?',['La Terre du Sud','La Terre de l’or','La Terre des rois']),V('Ce grand continent riche et tempéré existait vraiment.',0,'Faux : Cook prouve en 1774 qu’il n’existe pas.')],
 [W('Pourquoi les savants imaginaient-ils un continent au sud ?','Ils pensaient qu’il fallait des terres au sud pour équilibrer celles du nord : c’était une idée, sans preuve.'),Q('Qui prouve que ce continent n’existe pas ?',['James Cook','Christophe Colomb','Zheng He'])],
 'La Terra Australis est un continent imaginé par les savants ; il n’existe pas.'),
P('Si près de la Calédonie',M(),
 [V('Torres passe à l’ouest de la Nouvelle-Calédonie sans la voir.',1),Q('Quel passage franchit Torres ?',['Le détroit entre la Nouvelle-Guinée et l’Australie','Le détroit de Magellan','Le détroit de Gibraltar'])],
 [Q('Pourquoi le détroit ne porte-t-il le nom de Torres que 160 ans plus tard ?',['L’Espagne garde ses cartes secrètes','Torres l’avait interdit','Personne ne savait écrire son nom']),W('Pourquoi les royaumes gardaient-ils leurs cartes secrètes ?','Une carte est un trésor : elle donne les routes, les dangers et les terres à prendre ; la cacher empêche les rivaux d’en profiter.')],
 'Torres passe tout près de la Nouvelle-Calédonie sans la voir, puis franchit le détroit qui portera son nom.')],
f:{p:'Les Espagnols cherchent de l’[or] et la Terra Australis. Mendaña atteint les îles [Salomon]. Quirós arrive au [Vanuatu]. Torres passe tout près de la Nouvelle-Calédonie sans la [voir].',w:['épices','Philippines','acheter'],
 c:['Non : ils atteignent les Salomon, les Marquises, Santa Cruz et le Vanuatu, sans or ni continent ; Torres frôle la Nouvelle-Calédonie sans la voir. La Terra Australis riche et tempérée n’existe pas.','Oui : Quirós a trouvé le grand continent du Sud au Vanuatu.','Oui : Torres a découvert la Nouvelle-Calédonie en 1606.'],
 r:'Non. Mendaña cherche l’or légendaire de Salomon et atteint les îles Salomon (1568) ; son second voyage passe par les Marquises et Santa Cruz, puis Isabel Barreto mène la flotte à Manille. En 1606, Quirós croit avoir trouvé le continent du Sud au Vanuatu, mais ce n’est qu’une île. Torres passe à l’ouest de la Nouvelle-Calédonie sans la voir. Le grand continent riche et tempéré n’existait pas : Cook le prouvera en 1774.'}});

E(10,{q:'Abel Tasman a fait le tour de l’Australie… sans la voir. Comment est-ce possible ?',
h:['Il naviguait de nuit, sans lumière','Il est passé très au sud, puis à l’est, toujours loin des côtes','Il était aveugle'],
pg:[
P('Le navigateur de la Compagnie',I('tasman'),
 [Q('Pour qui travaille Abel Tasman ?',['La Compagnie hollandaise des Indes orientales','Le roi de France','Le roi d’Espagne']),V('Il part de Batavia (aujourd’hui Jakarta) en 1642.',1)],
 [Q('Que cherche la Compagnie ?',['Le continent du Sud et de nouveaux marchés','Des colons pour l’Amérique','Le pôle Nord']),W('En quoi une compagnie de marchands est-elle différente d’un roi qui envoie des explorateurs ?','Elle cherche avant tout le profit : elle paie des voyages pour trouver des marchandises et des clients, et juge leur réussite en argent.')],
 'En 1642, la Compagnie hollandaise des Indes orientales envoie Tasman chercher le continent du Sud.'),
P('La route de Tasman',[I('tasmanmap'),M()],
 [Q('Quelle île porte aujourd’hui le nom de Tasman ?',['La Tasmanie','Tahiti','Java']),V('Tasman passe très au sud de l’Australie.',1)],
 [W('Explique pourquoi Tasman ne voit jamais l’Australie.','Il descend très au sud pour profiter des vents d’ouest, passe au large de la côte sud, puis file vers l’est jusqu’à la Nouvelle-Zélande : il reste toujours loin des côtes australiennes.'),Q('Quel nom Tasman donne-t-il à la Tasmanie ?',['Terre de Van Diemen','Nouvelle-Hollande du Sud','Île Maurice'])],
 'Tasman passe très au sud, voit la Tasmanie, puis la Nouvelle-Zélande : il contourne l’Australie sans la voir.'),
P('La rencontre avec les Maoris',I('gilsemans'),
 [Q('Qui a fait ce dessin ?',['Le dessinateur de l’expédition de Tasman','Un Maori','Un photographe']),V('Tasman débarque en Nouvelle-Zélande.',0,'Faux : après l’attaque d’une chaloupe, il repart sans débarquer.')],
 [W('Ce dessin est fait par un Européen. Que faut-il garder en tête pour l’analyser ?','C’est le point de vue des Européens, qui ne comprennent pas les coutumes maories ; l’attaque peut s’expliquer par la défense du territoire ou par un malentendu.'),Q('Quel nom Tasman donne-t-il à la baie de la rencontre ?',['La baie des Meurtriers','La baie des Amis','La baie des Trésors'])],
 'En Nouvelle-Zélande, des Maoris attaquent une chaloupe : quatre marins sont tués, Tasman repart sans débarquer.'),
P('Le voyage, étape par étape',F('Le voyage d’Abel Tasman',[['14 août 1642','départ de Batavia'],['novembre 1642','Terre de Van Diemen (Tasmanie)'],['décembre 1642','Nouvelle-Zélande'],['janvier 1643','bon accueil aux Tonga'],['1643','récifs des Fidji, puis retour à Batavia']]),
 [O('Remets dans l’ordre.',['Batavia','Tasmanie','Nouvelle-Zélande','Tonga']),Q('Où Tasman est-il bien accueilli ?',['Aux Tonga','En Nouvelle-Zélande','En Australie'])],
 [Q('Pourquoi la Compagnie est-elle déçue ?',['Ni or, ni épices, ni nouveaux clients','Tasman a perdu tous ses navires','Il a découvert l’Amérique']),W('Ce voyage est un échec commercial. Est-il un échec pour la connaissance du monde ?','Non : il ajoute la Tasmanie, la Nouvelle-Zélande, Tonga et Fidji aux cartes européennes, et montre que l’Australie n’est pas rattachée à un continent plus au sud.')],
 'Tonga, Fidji, retour à Batavia : un échec pour les marchands, mais les cartes du Pacifique sud se remplissent.')],
f:{p:'En 1642, [Tasman] part de Batavia pour la Compagnie hollandaise. Il voit la [Tasmanie] et la Nouvelle-Zélande. Il passe très au [sud] de l’Australie, sans la voir. La Compagnie est [déçue].',w:['Cook','nord','ravie'],
 c:['Parti de Batavia, Tasman descend très au sud pour profiter des vents d’ouest, voit la Tasmanie puis la Nouvelle-Zélande et remonte par les Tonga et les Fidji : il contourne l’Australie en restant toujours loin de ses côtes.','Il a traversé l’Australie en tunnel.','Il a vu l’Australie mais a décidé de ne pas le dire.'],
 r:'Tasman part de Batavia en 1642 pour la Compagnie hollandaise des Indes orientales. Il passe par l’île Maurice, descend très au sud dans les vents d’ouest, aperçoit la Tasmanie (Terre de Van Diemen), puis la Nouvelle-Zélande, et revient par les Tonga, les Fidji et le nord de la Nouvelle-Guinée. Il a fait le tour de l’Australie en restant toujours au large : il ne l’a jamais vue. Pour la Compagnie, c’est un échec commercial.'}});

E(11,{q:'Pourquoi le voyage de Bougainville est-il différent des voyages précédents ?',
h:['Il cherche seulement de l’or','C’est une expédition de savants, au siècle des Lumières','Il voyage sur un bateau à vapeur'],
pg:[
P('Le capitaine et sa frégate',[I('bougainville'),I('boudeuse')],
 [Q('Quel roi confie ce voyage à Bougainville ?',['Louis XV','François Ier','Louis XVI']),V('C’est le premier tour du monde français.',1)],
 [Q('Qui embarque avec lui ?',['Un astronome et un naturaliste','Seulement des soldats','Des touristes']),W('Pourquoi emmener des savants sur un navire ?','Pour mesurer, dessiner et décrire les plantes, les animaux, les peuples et les côtes : on veut connaître le monde, pas seulement y faire du commerce.')],
 'En 1766, Bougainville part sur La Boudeuse avec un astronome et un naturaliste : c’est le siècle des Lumières.'),
P('La « Nouvelle-Cythère »',X('Tahiti, avril 1768','Texte adapté, d’après le « Voyage autour du monde » de Bougainville (1771)','Bougainville ne reste que neuf jours à Tahiti, en avril 1768. Dans son livre, il décrit une île merveilleuse, des fruits en abondance, des habitants accueillants et joyeux. Il la surnomme la « Nouvelle-Cythère », du nom de l’île de la déesse de l’amour dans les légendes grecques.\nSon récit fait rêver toute l’Europe : beaucoup imaginent Tahiti comme un paradis où l’on vivrait heureux sans travailler. Mais neuf jours suffisent-ils pour connaître un peuple ?','Bougainville reste neuf jours à Tahiti. Dans son livre, il dit que c’est une île merveilleuse, un paradis.\nToute l’Europe en rêve. Mais peut-on connaître un peuple en neuf jours ?'),
 [Q('Combien de jours Bougainville reste-t-il à Tahiti ?',['Neuf jours','Neuf ans','Un jour']),V('Son récit fait rêver toute l’Europe.',1)],
 [W('Pourquoi l’image de Tahiti comme « paradis » est-elle à discuter ?','En neuf jours, Bougainville voit peu de choses, ne parle pas la langue et décrit Tahiti avec ses rêves d’Européen. La société tahitienne avait ses règles, ses chefs et ses conflits.'),Q('Qui embarque avec Bougainville à Tahiti pour découvrir la France ?',['Ahutoru, un Tahitien','Tupaia','Lapu-Lapu'])],
 'Neuf jours à Tahiti suffisent pour faire rêver l’Europe ; le Tahitien Ahutoru part pour la France.'),
P('Si près de la Calédonie',M(),
 [Q('Comment Bougainville nomme-t-il le Vanuatu ?',['Les Grandes Cyclades','La Nouvelle-Cythère','Les Salomon']),V('Bougainville voit la Nouvelle-Calédonie.',0,'Faux : la Grande Barrière l’oblige à faire demi-tour avant.')],
 [Q('Pourquoi Bougainville fait-il demi-tour en juin 1768 ?',['Les récifs de la Grande Barrière barrent la route','Il a trouvé l’Australie','Le roi le rappelle']),W('Pourquoi l’équipage finit-il par manger les rats du bord ?','Après des mois de mer, les vivres sont épuisés : les marins ont faim et n’ont plus rien d’autre.')],
 'Bougainville traverse le Vanuatu, mais la Grande Barrière l’arrête : il ne voit ni l’Australie ni la Calédonie.'),
P('Une femme autour du monde',[I('bougainvillier'),X('Jeanne Barret','Texte de l’atlas, d’après le récit de Bougainville','Le naturaliste Philibert Commerson a un aide qui porte les caisses de plantes et l’accompagne dans toutes ses excursions. À Tahiti, les habitants découvrent son secret : c’est une femme, déguisée en homme ! Elle s’appelle Jeanne Barret.\nÀ l’époque, les femmes n’ont pas le droit de monter sur les navires de la Marine royale. Jeanne Barret poursuit pourtant le voyage avec Commerson ; elle rentrera en France quelques années plus tard : c’est la première femme connue à avoir fait le tour du monde.','L’aide du savant Commerson cache un secret : c’est une femme habillée en homme ! Elle s’appelle Jeanne Barret.\nLes femmes n’avaient pas le droit d’embarquer. Elle est la première femme connue à avoir fait le tour du monde.')],
 [Q('Qui est Jeanne Barret ?',['L’aide du naturaliste, une femme déguisée en homme','La reine de France','Une Tahitienne']),V('Le bougainvillier porte le nom du capitaine.',1)],
 [W('Pourquoi Jeanne Barret a-t-elle dû se déguiser ?','Les femmes n’avaient pas le droit d’embarquer sur les navires de la Marine royale : pour participer à l’expédition, elle s’est fait passer pour un homme.'),Q('Où a-t-on découvert le bougainvillier ?',['Au Brésil','En France','À Tahiti'])],
 'Jeanne Barret, déguisée en homme, est la première femme connue à faire le tour du monde ; les savants rapportent des plantes comme le bougainvillier.')],
f:{p:'En 1766, [Bougainville] part pour le premier tour du monde français. À bord, il y a des [savants]. À [Tahiti], il reste neuf jours. Jeanne Barret est la première [femme] à faire le tour du monde.',w:['Cook','pirates','Paris'],
 c:['C’est une expédition des Lumières : on emmène des savants pour observer, mesurer et décrire la nature et les peuples, plus que pour chercher de l’or ou des épices.','Bougainville part uniquement pour conquérir de l’or.','C’est le premier voyage en bateau à moteur.'],
 r:'Le voyage de Bougainville (1766 – 1769), premier tour du monde français, est une expédition du siècle des Lumières : un astronome et le naturaliste Commerson sont à bord pour mesurer, décrire les plantes, les animaux et les peuples. Son récit sur Tahiti fait rêver l’Europe. Il manque de peu la Nouvelle-Calédonie. Jeanne Barret, l’aide de Commerson, devient la première femme connue à faire le tour du monde.'}});

E(12,{q:'Pourquoi dit-on que James Cook a presque achevé la carte du Pacifique ?',
h:['Il a fait un seul petit voyage','En trois voyages, il a parcouru tout le Pacifique, des glaces du sud au nord, avec des instruments précis','Il a recopié les cartes des autres'],
pg:[
P('Un marin et un navire',[I('cook'),I('endeavour')],
 [Q('Comment s’appelle le navire de Cook lors du premier voyage ?',['L’Endeavour','La Boudeuse','La Victoria']),V('Cook est fils de paysan.',1)],
 [Q('Quelle est la mission officielle du premier voyage ?',['Observer à Tahiti le passage de Vénus devant le Soleil','Trouver de l’or','Faire la guerre à la France']),W('Pourquoi le passage de Vénus intéresse-t-il les savants ?','En l’observant depuis plusieurs points de la Terre, on peut calculer la distance entre la Terre et le Soleil.')],
 'En 1768, Cook part sur l’Endeavour : mission officielle à Tahiti, mission secrète vers le continent du Sud.'),
P('Trois voyages',TB('Les trois voyages de James Cook',['Voyage','Navires','Grandes étapes'],[['1768 – 1771','Endeavour','Tahiti, carte de la Nouvelle-Zélande, côte est de l’Australie'],['1772 – 1775','Resolution et Adventure','cercle polaire antarctique, île de Pâques, Nouvelle-Calédonie (1774)'],['1776 – 1779','Resolution et Discovery','Hawaï, Alaska, détroit de Béring ; mort de Cook à Hawaï']],'Tableau de l’atlas.'),
 [Q('Combien de voyages Cook fait-il ?',['Trois','Un','Sept']),Q('Pendant quel voyage arrive-t-il en Nouvelle-Calédonie ?',['Le deuxième (1772 – 1775)','Le premier','Le troisième'])],
 [W('Comment Cook évite-t-il le scorbut à ses marins ?','Il impose la propreté, la choucroute et des produits frais à chaque escale : presque aucun marin n’en meurt, ce qui est une révolution.'),V('Cook a cherché un passage par le nord entre le Pacifique et l’Atlantique.',1)],
 'Trois voyages, de 1768 à 1779 : Nouvelle-Zélande, Australie, glaces du sud, Nouvelle-Calédonie, Hawaï, Alaska.'),
P('Balade, septembre 1774',I('hodges'),
 [Q('Où Cook aborde-t-il en Nouvelle-Calédonie ?',['À Balade','À Nouméa','À Bourail']),V('Cook est bien accueilli par les Kanak.',1)],
 [Q('Pourquoi Cook nomme-t-il l’île « New Caledonia » ?',['Les montagnes lui rappellent l’Écosse (Caledonia en latin)','C’était le nom donné par les Kanak','En l’honneur du roi de France']),W('Ce portrait est fait par William Hodges, peintre de l’expédition. Qu’apporte-t-il à l’historien ?','Un témoignage visuel de 1774 sur un homme de Balade (coiffure, parures), vu par un artiste européen : précieux, mais c’est son regard à lui.')],
 'En septembre 1774, Cook aborde à Balade, bien accueilli par les Kanak, et nomme l’île « New Caledonia ».'),
P('La carte se remplit',[I('carte1774'),M()],
 [Q('Où Cook est-il tué en 1779 ?',['À Hawaï','En Nouvelle-Calédonie','À Londres']),V('Cook prouve que le grand continent du Sud, riche et tempéré, n’existe pas.',1)],
 [Q('Quel instrument aide Cook à calculer précisément sa longitude ?',['Le chronomètre de marine','La boussole','Le GPS']),W('Pourquoi la carte du Pacifique est-elle presque complète après Cook ?','Il a parcouru le Pacifique du cercle antarctique au détroit de Béring, cartographié la Nouvelle-Zélande, la côte est de l’Australie et de nombreuses îles, avec des mesures précises grâce au chronomètre.')],
 'Grâce au chronomètre, Cook dresse des cartes précises ; à sa mort (1779), la carte du Pacifique est presque complète.')],
f:{p:'[Cook] fait trois voyages dans le Pacifique. Il cartographie la Nouvelle-Zélande et l’[Australie]. En 1774, il nomme la [Nouvelle-Calédonie]. Grâce au [chronomètre], ses cartes sont très précises.',w:['Colomb','Amérique','téléphone'],
 c:['En trois voyages (1768 – 1779), Cook parcourt le Pacifique des glaces de l’Antarctique jusqu’au détroit de Béring, cartographie la Nouvelle-Zélande, l’est de l’Australie et de nombreuses îles avec un chronomètre, et prouve que le continent austral rêvé n’existe pas.','Cook a fait un seul voyage, à Tahiti.','Cook a recopié les cartes de Colomb.'],
 r:'En trois voyages (1768 – 1779), James Cook explore tout le Pacifique : carte de la Nouvelle-Zélande et de la côte est de l’Australie, record de 71° sud dans les glaces (preuve que le grand continent tempéré n’existe pas), Nouvelle-Calédonie (1774), Hawaï, Alaska et détroit de Béring. Le chronomètre lui donne des longitudes précises et il protège ses marins du scorbut. À sa mort en 1779, la carte du Pacifique est presque complète.'}});

E(13,{q:'Qu’est-il arrivé à l’expédition de La Pérouse ?',
h:['Elle est rentrée en France sans problème','Ses deux frégates ont fait naufrage à Vanikoro, et on ne l’a su que 40 ans plus tard','Elle s’est installée à Tahiti pour toujours'],
pg:[
P('Les instructions du roi',I('louis16'),
 [Q('Quel roi envoie La Pérouse ?',['Louis XVI','Louis XIV','Napoléon']),V('L’expédition emmène des savants et des artistes.',1)],
 [Q('Que veut le roi ?',['Compléter l’œuvre de Cook','Conquérir l’Amérique','Ramener des épices']),W('Ce tableau a été peint en 1817, bien après la mort du roi et de La Pérouse. Pourquoi peindre cette scène ?','Pour honorer leur mémoire et célébrer la science française ; la scène est reconstituée, ce n’est pas un témoignage direct.')],
 'En 1785, Louis XVI envoie La Pérouse compléter l’œuvre de Cook, avec deux frégates et des savants.'),
P('Le voyage, étape par étape',F('Le voyage de La Pérouse',[['1er août 1785','départ de Brest avec La Boussole et L’Astrolabe'],['1786','île de Pâques, Hawaï, Alaska (21 marins noyés)'],['1787','côtes d’Asie : Macao, Corée, Japon'],['septembre 1787','au Kamtchatka, Lesseps part avec les journaux'],['décembre 1787','aux Samoa, douze hommes sont tués'],['janvier – mars 1788','Botany Bay : dernières lettres'],['1788','disparition']]),
 [O('Remets dans l’ordre.',['Brest','Alaska','Kamtchatka','Botany Bay']),V('Lesseps traverse la Russie pour rapporter les journaux.',1)],
 [W('Pourquoi La Pérouse confie-t-il ses journaux à Lesseps au Kamtchatka ?','Pour que les découvertes arrivent en France même si l’expédition disparaît : il les met à l’abri en les envoyant par la terre.'),Q('Combien de temps dure le voyage de Lesseps jusqu’à Versailles ?',['Environ un an','Une semaine','Dix ans'])],
 'De Brest à l’Alaska, l’Asie, le Kamtchatka puis Botany Bay ; les journaux partent pour la France par la Russie.'),
P('« A-t-on des nouvelles ? »',X('La disparition','Texte de l’atlas','En janvier 1788, à Botany Bay, en Australie, La Pérouse croise les premiers colons anglais, qui viennent d’arriver. Il leur confie ses dernières lettres. Il annonce qu’il va explorer les côtes de la Nouvelle-Calédonie, puis rentrer.\nOn ne le reverra jamais. En 1791, la France envoie d’Entrecasteaux à sa recherche ; celui-ci explore les côtes calédoniennes en 1792 – 1793, sans le trouver. La tradition raconte qu’avant d’être exécuté, en 1793, Louis XVI aurait demandé : « A-t-on des nouvelles de M. de La Pérouse ? »','En 1788, La Pérouse envoie ses dernières lettres d’Australie. Puis il disparaît.\nD’Entrecasteaux part le chercher et explore les côtes de la Calédonie. Il ne le trouve pas.'),
 [Q('D’où La Pérouse envoie-t-il ses dernières lettres ?',['De Botany Bay, en Australie','De Brest','De Tahiti']),V('D’Entrecasteaux part à la recherche de La Pérouse.',1)],
 [Q('Pourquoi l’atlas écrit-il « aurait demandé » ?',['Parce que cette phrase vient de la tradition et n’est pas prouvée','Parce que Louis XVI ne parlait pas français','Parce que la phrase est inventée par l’atlas']),W('Quelle conséquence la disparition de La Pérouse a-t-elle pour la Nouvelle-Calédonie ?','Elle provoque l’expédition de d’Entrecasteaux, qui explore et cartographie les côtes calédoniennes en 1792 – 1793.')],
 'Après Botany Bay (1788), La Pérouse disparaît ; d’Entrecasteaux, parti le chercher, explore les côtes calédoniennes.'),
P('L’épave',[I('vanikoro'),M()],
 [Q('Où les épaves ont-elles été retrouvées ?',['À Vanikoro, aux îles Salomon','En Nouvelle-Calédonie','En France']),V('On retrouve les épaves environ 40 ans après le naufrage.',1)],
 [Q('Comment les frégates ont-elles fait naufrage ?',['Elles se sont brisées sur le récif','Elles ont été coulées par les Anglais','Elles ont brûlé dans un port']),W('Comment peut-on encore enquêter aujourd’hui sur ce naufrage ?','En fouillant les épaves et le site de Vanikoro (objets, instruments, restes humains) et en écoutant les récits transmis par les habitants de l’île.')],
 'Quarante ans plus tard, on retrouve les épaves à Vanikoro : les deux frégates se sont brisées sur le récif.')],
f:{p:'En 1785, [La Pérouse] part de Brest avec deux frégates. Il envoie ses journaux en France depuis le [Kamtchatka]. En 1788, il disparaît. On retrouve ses épaves à [Vanikoro], brisées sur un [récif].',w:['Colomb','Tahiti','iceberg'],
 c:['Après Botany Bay (1788), ses deux frégates se sont brisées sur le récif de Vanikoro, aux îles Salomon ; on ne l’a appris qu’environ quarante ans plus tard. Ses journaux, envoyés depuis le Kamtchatka, ont été sauvés.','Il est rentré en France en 1789 et a raconté son voyage au roi.','Il a été retrouvé vivant en Nouvelle-Calédonie par d’Entrecasteaux.'],
 r:'Parti de Brest en 1785, La Pérouse explore le Pacifique nord, l’Alaska et les côtes d’Asie ; il envoie ses journaux en France depuis le Kamtchatka (Lesseps). En 1788, après ses dernières lettres de Botany Bay, il disparaît. D’Entrecasteaux le cherche en vain (et explore la Nouvelle-Calédonie). Environ quarante ans plus tard, on retrouve les épaves à Vanikoro, aux îles Salomon : les deux frégates s’étaient brisées sur le récif.'}});

E(14,{q:'Comment les Grandes Découvertes ont-elles changé le monde ?',
h:['Elles n’ont presque rien changé','Elles ont relié tous les continents, pour le meilleur et pour le pire','Elles n’ont changé que la vie des Européens'],
pg:[
P('Une nouvelle image du monde',I('mercator'),
 [Q('En quelle année Mercator dessine-t-il cette carte ?',['1569','1450','2000']),V('On y voit l’Amérique.',1)],
 [Q('Compare avec la carte de Fra Mauro (vers 1450). Qu’est-ce qui a changé ?',['L’Amérique et le Pacifique apparaissent : la carte montre presque tout le globe','Rien du tout','L’Afrique a disparu']),W('Pourquoi dit-on qu’en 34 ans (1488 – 1522) l’image du monde a complètement changé ?','De Dias à Elcano, une seule génération de marins a contourné l’Afrique, atteint l’Amérique, traversé le Pacifique et fait le tour de la Terre.')],
 'En moins d’un siècle, les cartes montrent presque tout le globe : tous les océans sont reliés.'),
P('L’échange colombien',[I('crops'),TB('Ce qui traverse l’Atlantique',['De l’Amérique vers le reste du monde','Du reste du monde vers l’Amérique'],[['maïs, pomme de terre','blé, riz'],['tomate, cacao','cheval, vache, cochon'],['tabac, haricot','canne à sucre, café'],['dinde','maladies : variole, rougeole']],'Tableau de l’atlas.')],
 [Q('D’où vient le maïs ?',['D’Amérique','D’Europe','D’Asie']),Q('Quel animal arrive en Amérique avec les Européens ?',['Le cheval','Le lama','Le jaguar'])],
 [W('Pourquoi parle-t-on d’« échange » colombien ?','Plantes, animaux et maladies circulent dans les deux sens entre l’Amérique et le reste du monde, à partir du voyage de Colomb.'),Q('Quelle a été la conséquence la plus dramatique de cet échange ?',['Des maladies comme la variole tuent des millions d’Amérindiens','La pomme de terre devient chère','Les chevaux disparaissent'])],
 'Plantes, animaux et maladies traversent l’océan : maïs et pomme de terre vers l’Europe, cheval et variole vers l’Amérique.'),
P('La traite atlantique',X('Des empires et des esclaves','Texte de l’atlas','Espagnols et Portugais conquièrent d’immenses territoires en Amérique. Pour exploiter les mines d’or et d’argent et les plantations de canne à sucre, il faut beaucoup de travailleurs. Les Amérindiens meurent en grand nombre, de maladies et de mauvais traitements.\nLes Européens achètent alors en Afrique des millions d’hommes, de femmes et d’enfants réduits en esclavage et les déportent de force en Amérique : c’est la traite atlantique. Elle dure plus de trois siècles. En France, une loi de 2001 la reconnaît comme un crime contre l’humanité.','Les Européens prennent de grands territoires en Amérique. Ils veulent des travailleurs pour les mines et les champs.\nIls achètent en Afrique des millions de personnes réduites en esclavage et les emmènent de force en Amérique. C’est la traite. C’est un crime contre l’humanité.'),
 [Q('Où les Africains réduits en esclavage sont-ils déportés ?',['En Amérique','En Chine','En Australie']),V('La traite atlantique a duré plus de trois siècles.',1)],
 [W('Quel lien y a-t-il entre la mort de nombreux Amérindiens et le développement de la traite ?','Les Amérindiens meurent en masse (maladies, violences) ; pour les remplacer dans les mines et les plantations, les Européens déportent des Africains réduits en esclavage.'),Q('Comment la loi française de 2001 qualifie-t-elle la traite et l’esclavage ?',['Un crime contre l’humanité','Une erreur sans importance','Un commerce normal'])],
 'Conquêtes, mines, plantations : des millions d’Africains sont déportés en Amérique (traite atlantique).'),
P('Découvertes… ou rencontres ?',M(),
 [Q('Ces terres étaient-elles vides avant l’arrivée des Européens ?',['Non, elles étaient habitées depuis des milliers d’années','Oui, totalement vides','On ne le sait pas']),V('Pour la première fois, des navires font le tour de la Terre.',1)],
 [Q('Pourquoi les historiens préfèrent-ils parler de « mise en contact » ?',['Parce que ces terres étaient déjà habitées et connues de leurs habitants','Parce que le mot « découverte » est trop long','Parce que les Européens ne sont jamais arrivés']),W('Les Grandes Découvertes sont-elles le début de la mondialisation ? Argumente.','En partie oui : pour la première fois, tous les continents sont reliés par la mer ; plantes, marchandises, idées et personnes circulent à l’échelle du globe. Mais ces échanges sont très inégaux : conquêtes, maladies, esclavage.')],
 'Ces terres étaient habitées : on parle aujourd’hui de « mise en contact » des parties du monde.')],
f:{p:'Les Grandes Découvertes relient tous les [continents]. Les plantes et les animaux voyagent : c’est l’échange [colombien]. Des millions d’Africains sont déportés : c’est la [traite]. Ces terres étaient déjà [habitées].',w:['planètes','chinois','vides'],
 c:['Elles relient pour la première fois tous les continents : échanges de plantes, d’animaux et d’idées, mais aussi conquêtes, maladies qui tuent des millions d’Amérindiens et traite des Africains.','Elles n’ont rien changé : chaque continent est resté isolé.','Elles n’ont changé que les cartes, sans conséquence pour les peuples.'],
 r:'Entre 1488 et 1522, une génération de marins relie tous les océans : le monde devient un. Plantes, animaux, marchandises et idées circulent (échange colombien : maïs, pomme de terre vers l’Europe, cheval, blé vers l’Amérique). Mais les maladies tuent des millions d’Amérindiens, l’Espagne et le Portugal bâtissent des empires, et des millions d’Africains sont déportés (traite atlantique). Ces terres étant habitées, on parle aujourd’hui de « mise en contact » plutôt que de « découvertes ».'}});
})();
